INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 1, 'theory', 'Quiz: the birth of JavaScript');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 0, 'Why did the language get the name JavaScript?', '["It was built on top of Java", "It was written by Sun", "It compiles to Java bytecode", "It is a marketing trick: Netscape struck a deal with Sun, and the language has nothing to do with Java"]', 3, 'The first prototype was called Mocha, then LiveScript; the name JavaScript appeared in December 1995 because of Java''s popularity.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 1, 'Where did JavaScript get functions as values and closures?', '["From Scheme", "From C", "From Java", "From Python"]', 0, 'Brendan Eich was hired to embed Scheme in the browser; the functional ideas stayed, while the syntax was made to look like Java and C.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 2, 'What is ECMAScript?', '["A browser from Microsoft", "A library for working with the DOM", "The name of the standard the language is implemented from; JavaScript is a trademark and the best-known implementation", "An extension of the HTTP protocol"]', 2, 'Netscape handed the language to Ecma International; the ECMA-262 standard came out in 1997, and the TC39 committee develops it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 3, 'What did Gmail and Google Maps do in 2004–2005?', '["Replaced JavaScript with Flash", "Showed that a page can request data in the background without a reload — the approach was named Ajax", "Introduced modules into the language", "Created the JSON standard"]', 1, 'The XMLHttpRequest object had existed since 1999, but it was these applications that brought it real fame.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 4, 'What did the release of Chrome with the V8 engine in 2008 bring?', '["The npm package manager", "Classes in the language", "Abandoning the ECMAScript standard", "Compiling JavaScript to machine code on the fly and a performance race between browsers"]', 3, 'V8 turned JavaScript from a “language for decoration” into a fast language in which big programs can be written.');
